/// Rewrites integer `+`, `-` and `*` in a function body into checked
/// operations that panic with a descriptive message on overflow.
///
/// ```
/// use my_macros::checked_arith;
///
/// #[checked_arith]
/// fn add(a: u8, b: u8) -> u8 {
///     a + b
/// }
///
/// assert_eq!(add(1, 2), 3);
/// ```
